"""Deterministic and explainable early warning rule engine.

Monitors operational infrastructure indicators against configurable thresholds
to detect physical slippage, critical land bottlenecks, clearance delays,
inflation spikes, and turnover risks.
"""

from typing import Any, Dict, List

import pandas as pd
from pydantic import BaseModel, Field

from infrastructure_risk.config import EARLY_WARNING_THRESHOLDS


class WarningAlert(BaseModel):
    """Structured early warning alert generated by the rule engine."""

    warning_id: str = Field(..., description="Unique warning code")
    project_id: str = Field(..., description="Project ID being evaluated")
    severity: str = Field(..., description="Severity level: High, Medium, or Low")
    condition: str = Field(..., description="Indicator condition that triggered the warning")
    observed_value: Any = Field(..., description="Actual value observed in project record")
    threshold_rule: str = Field(..., description="Configured rule threshold")
    explanation: str = Field(..., description="Human-readable root cause explanation")
    suggested_action: str = Field(..., description="Recommended action for project monitoring committee")


def evaluate_project_warnings(
    project: pd.Series,
    thresholds: Dict[str, Any] = EARLY_WARNING_THRESHOLDS,
) -> List[WarningAlert]:
    """Evaluate a single project against deterministic early warning rules.

    Args:
        project: A pandas Series or dict-like object with project indicators.
        thresholds: Dictionary of threshold values.

    Returns:
        List of WarningAlert objects for any triggered rules.
    """
    alerts: List[WarningAlert] = []
    pid = str(project.get("project_id", "UNKNOWN"))

    # Extract indicators
    planned_duration = float(project.get("planned_duration_months", 1.0))
    elapsed_months = float(project.get("elapsed_months", 0.0))
    physical_progress = float(project.get("physical_progress_pct", 0.0))
    land_acq = float(project.get("land_acquisition_pct", 100.0))
    approval_delay = float(project.get("approval_delay_months", 0.0))
    funding_risk = str(project.get("funding_risk", "Low"))
    contractor_changes = int(project.get("contractor_changes", 0))
    material_inflation = float(project.get("material_inflation_pct", 0.0))

    # Calculate Progress Benchmark
    # Expected progress fraction = elapsed / planned
    elapsed_ratio = min(max(elapsed_months / planned_duration, 0.0), 1.5)
    expected_progress = min(elapsed_ratio * 100.0, 100.0)
    progress_slippage = expected_progress - physical_progress

    # Rule 1: Severe Physical Progress Slippage
    slippage_threshold = thresholds.get("progress_slippage_gap_pct", 15.0)
    if progress_slippage >= slippage_threshold and elapsed_ratio >= 0.20:
        severity = "High" if progress_slippage >= 25.0 else "Medium"
        alerts.append(
            WarningAlert(
                warning_id="WARN-SCHED-01",
                project_id=pid,
                severity=severity,
                condition="Physical Progress Gap vs Schedule Benchmark",
                observed_value=f"Actual: {physical_progress:.1f}%, Expected: {expected_progress:.1f}% (Gap: {progress_slippage:.1f}%)",
                threshold_rule=f"Gap >= {slippage_threshold:.1f}% after 20% timeline elapsed",
                explanation="Work completion rate is materially trailing planned milestone schedule.",
                suggested_action="Convene milestone recovery meeting with executing agency; review work breakdown structure and critical path bottlenecks.",
            )
        )

    # Rule 2: Land Acquisition Bottleneck
    land_threshold = thresholds.get("land_acquisition_critical_pct", 60.0)
    if elapsed_ratio >= 0.40 and land_acq < land_threshold:
        alerts.append(
            WarningAlert(
                warning_id="WARN-LAND-02",
                project_id=pid,
                severity="High",
                condition="Critical Right-of-Way / Land Acquisition Deficit",
                observed_value=f"{land_acq:.1f}% land acquired (Elapsed: {elapsed_ratio*100:.1f}%)",
                threshold_rule=f"Land < {land_threshold:.1f}% with elapsed timeline >= 40%",
                explanation="Unresolved land acquisition or compensation disbursement threatens civil works continuity and invites contractor idling claims.",
                suggested_action="Escalate to District Collector / State Revenue Authority for expedited notification and award under land acquisition statutes.",
            )
        )

    # Rule 3: Extended Regulatory / Statutory Clearance Delay
    approval_thresh = thresholds.get("approval_delay_critical_months", 6.0)
    if approval_delay >= approval_thresh:
        alerts.append(
            WarningAlert(
                warning_id="WARN-STAT-03",
                project_id=pid,
                severity="High" if approval_delay >= 12.0 else "Medium",
                condition="Protracted Statutory / Environmental Approval Delays",
                observed_value=f"{approval_delay:.1f} months delay",
                threshold_rule=f"Approval Delay >= {approval_thresh:.1f} months",
                explanation="Delays in forest clearances, environmental permissions, or utility shifting are impeding full site handover.",
                suggested_action="Engage Project Monitoring Group (PMG) / single-window nodal cell for inter-ministerial resolution.",
            )
        )

    # Rule 4: Frequent Contractor Replacements
    turnover_thresh = thresholds.get("high_contractor_changes", 2)
    if contractor_changes >= turnover_thresh:
        alerts.append(
            WarningAlert(
                warning_id="WARN-EXEC-04",
                project_id=pid,
                severity="High",
                condition="Frequent Contractor Replacement / Contractual Disputes",
                observed_value=f"{contractor_changes} contractor changes",
                threshold_rule=f"Contractor changes >= {turnover_thresh}",
                explanation="Repeated re-tendering and contractor churn causes mobilization gaps, design transition risks, and litigation overhead.",
                suggested_action="Conduct forensic contract audit; evaluate bank guarantees, dispute arbitration status, and financial capability of replacement contractor.",
            )
        )

    # Rule 5: Severe Material Price Inflation Shock
    inflation_thresh = thresholds.get("elevated_material_inflation_pct", 12.0)
    if material_inflation >= inflation_thresh:
        alerts.append(
            WarningAlert(
                warning_id="WARN-COST-05",
                project_id=pid,
                severity="Medium" if material_inflation < 18.0 else "High",
                condition="High Input Material Escalation / Commodity Shock",
                observed_value=f"{material_inflation:.1f}% material inflation",
                threshold_rule=f"Material inflation >= {inflation_thresh:.1f}%",
                explanation="Spikes in bulk cement, structural steel, or bitumen exceed standard contract price adjustment indexation clauses.",
                suggested_action="Review price variation clause (PVC) liability; evaluate contingency fund adequacy and hedge procurement requirements.",
            )
        )

    # Rule 6: High Funding Risk Flag
    if funding_risk == "High":
        alerts.append(
            WarningAlert(
                warning_id="WARN-FIN-06",
                project_id=pid,
                severity="High",
                condition="High Project Funding / Liquidity Risk",
                observed_value=funding_risk,
                threshold_rule="funding_risk == 'High'",
                explanation="Interrupted budgetary allocations or escrow shortfall risks halting contractor cash flows.",
                suggested_action="Verify central/state co-financing disbursements, loan drawdowns, and expenditure authorization sanction.",
            )
        )

    return alerts


def evaluate_batch_warnings(
    df: pd.DataFrame,
    thresholds: Dict[str, Any] = EARLY_WARNING_THRESHOLDS,
) -> pd.DataFrame:
    """Evaluate warning rules across an entire DataFrame of projects.

    Returns:
        DataFrame with columns: [project_id, warning_id, severity, condition, observed_value, threshold_rule, explanation, suggested_action]
    """
    records = []
    for _, row in df.iterrows():
        alerts = evaluate_project_warnings(row, thresholds)
        for a in alerts:
            records.append(a.model_dump())

    if not records:
        return pd.DataFrame(
            columns=[
                "warning_id",
                "project_id",
                "severity",
                "condition",
                "observed_value",
                "threshold_rule",
                "explanation",
                "suggested_action",
            ]
        )

    return pd.DataFrame(records)
